# HLLSet core for Packet Tracer SBC Python.
# PT Python runs on a JavaScript engine: integers are doubles (exact only up to 2^53)
# and bitwise ops are 32-bit. So every 64-bit value is 4 limbs of 16 bits,
# little-endian: [bits 0-15, 16-31, 32-47, 48-63]. Bitwise ops only touch values < 2^16,
# products of two limbs stay < 2^32 (exact in a double) and are split with % and //.
# Bit-exact with hllset-core: h = murmur3_x64_128(utf8(token), seed as u32).low64,
# reg = h & 0x3FF, tz = min(ctz(h >> 10), 31).

L16 = 65536
C1 = [0x53d5, 0x1142, 0x7b91, 0x87c3]   # 0x87c37b91114253d5
C2 = [0x937f, 0x2745, 0xad43, 0x4cf5]   # 0x4cf5ad432745937f
F1 = [0x8ccd, 0xed55, 0xafd7, 0xff51]   # 0xff51afd7ed558ccd
F2 = [0xec53, 0x1a85, 0xb9fe, 0xc4ce]   # 0xc4ceb9fe1a85ec53
A1 = [0xe729, 0x52dc, 0, 0]             # 0x52dce729
A2 = [0x5ab5, 0x3849, 0, 0]             # 0x38495ab5
FIVE = [5, 0, 0, 0]


def small(n):
    # non-negative int < 2^48 -> limbs (arithmetic only)
    r = []
    for i in range(4):
        q = n // L16
        r.append(n - q * L16)
        n = q
    return r


def add(a, b):
    r = [0, 0, 0, 0]
    c = 0
    for i in range(4):
        s = a[i] + b[i] + c
        c = s // L16
        r[i] = s - c * L16
    return r


def mul(a, b):
    # (a * b) mod 2^64
    acc = [0, 0, 0, 0]
    for i in range(4):
        for j in range(4 - i):
            acc[i + j] = acc[i + j] + a[i] * b[j]
    r = [0, 0, 0, 0]
    c = 0
    for k in range(4):
        s = acc[k] + c
        c = s // L16
        r[k] = s - c * L16
    return r


def xor(a, b):
    return [a[0] ^ b[0], a[1] ^ b[1], a[2] ^ b[2], a[3] ^ b[3]]


def rotl(x, r):
    q = r // 16
    s = r - q * 16
    y = [x[(i - q + 4) % 4] for i in range(4)]
    if s == 0:
        return y
    return [((y[i] << s) & 0xFFFF) | (y[(i + 3) % 4] >> (16 - s)) for i in range(4)]


def shr(x, r):
    q = r // 16
    s = r - q * 16
    y = [0, 0, 0, 0]
    for i in range(4):
        if i + q < 4:
            y[i] = x[i + q]
    if s == 0:
        return y
    out = []
    for i in range(4):
        hi = y[i + 1] if i < 3 else 0
        out.append((y[i] >> s) | ((hi << (16 - s)) & 0xFFFF))
    return out


def fmix(k):
    k = xor(k, shr(k, 33))
    k = mul(k, F1)
    k = xor(k, shr(k, 33))
    k = mul(k, F2)
    k = xor(k, shr(k, 33))
    return k


def utf8(s):
    out = []
    for ch in s:
        c = ord(ch)
        if c < 0x80:
            out.append(c)
        elif c < 0x800:
            out.append(0xC0 | (c >> 6))
            out.append(0x80 | (c & 0x3F))
        elif c < 0x10000:
            out.append(0xE0 | (c >> 12))
            out.append(0x80 | ((c >> 6) & 0x3F))
            out.append(0x80 | (c & 0x3F))
        else:
            out.append(0xF0 | (c >> 18))
            out.append(0x80 | ((c >> 12) & 0x3F))
            out.append(0x80 | ((c >> 6) & 0x3F))
            out.append(0x80 | (c & 0x3F))
    return out


def word(d, i, n):
    # n (<= 8) little-endian bytes starting at d[i] -> limbs
    r = [0, 0, 0, 0]
    for j in range(n):
        r[j // 2] = r[j // 2] | (d[i + j] << (8 * (j % 2)))
    return r


def murmur64(text, seed):
    d = utf8(text)
    n = len(d)
    s32 = seed % 4294967296
    h1 = small(s32)
    h2 = small(s32)
    nb = n // 16
    for b in range(nb):
        k1 = word(d, b * 16, 8)
        k2 = word(d, b * 16 + 8, 8)
        k1 = mul(rotl(mul(k1, C1), 31), C2)
        h1 = xor(h1, k1)
        h1 = add(mul(add(rotl(h1, 27), h2), FIVE), A1)
        k2 = mul(rotl(mul(k2, C2), 33), C1)
        h2 = xor(h2, k2)
        h2 = add(mul(add(rotl(h2, 31), h1), FIVE), A2)
    t = nb * 16
    rest = n - t
    if rest > 8:
        k2 = word(d, t + 8, rest - 8)
        h2 = xor(h2, mul(rotl(mul(k2, C2), 33), C1))
    if rest > 0:
        k1 = word(d, t, min(rest, 8))
        h1 = xor(h1, mul(rotl(mul(k1, C1), 31), C2))
    ln = small(n)
    h1 = xor(h1, ln)
    h2 = xor(h2, ln)
    h1 = add(h1, h2)
    h2 = add(h2, h1)
    h1 = fmix(h1)
    h2 = fmix(h2)
    return add(h1, h2)


def hex64(x):
    digits = "0123456789abcdef"
    s = ""
    for i in range(3, -1, -1):
        v = x[i]
        for k in (12, 8, 4, 0):
            s = s + digits[(v >> k) & 15]
    return "0x" + s


def ctz(x):
    for i in range(4):
        if x[i] != 0:
            v = x[i]
            c = 0
            while (v & 1) == 0:
                v = v >> 1
                c = c + 1
            return i * 16 + c
    return 64


def position(text, seed):
    h = murmur64(text, seed)
    reg = h[0] & 0x3FF
    tz = ctz(shr(h, 10))
    if tz > 31:
        tz = 31
    return reg, tz

# ---------------- common: SHA-1, line protocol over PT tcp ----------------
# Wire format: one message per line, fields separated by "|":  <rid>|<CMD>|<arg>|...
# rid = request id; replies reuse the rid of the request.
# Handshake: client sends "0|HELLO|<name>" until it gets "0|WELCOME|<name>".

TICK = [0]          # main-loop tick counter (0.5 s per tick)
TIMEOUT_TICKS = 30  # 15 s


def log(tag, text):
    print("[" + tag + "] " + text)


def clean(s):
    # strip protocol delimiters from user data
    out = ""
    for ch in s:
        if ch in "|;,:~\n\r\t":
            continue
        out = out + ch
    return out


def tokenize(text):
    toks = []
    for raw in text.lower().split(" "):
        t = ""
        for ch in raw:
            if ch in ".!?\"'()[]{}<>|;,:~\n\r\t":
                continue
            t = t + ch
        if t != "":
            toks.append(t)
    return toks


# ---- SHA-1 on 16-bit halves: word = [lo, hi] ----
def _w(v):
    hi = v // 65536
    return [v - hi * 65536, hi]


def _add(a, b):
    lo = a[0] + b[0]
    c = lo // 65536
    hi = a[1] + b[1] + c
    return [lo - c * 65536, hi % 65536]


def _rotl(x, n):
    lo = x[0]
    hi = x[1]
    if n >= 16:
        lo, hi = hi, lo
        n = n - 16
    if n == 0:
        return [lo, hi]
    return [((lo << n) & 0xFFFF) | (hi >> (16 - n)), ((hi << n) & 0xFFFF) | (lo >> (16 - n))]


def sha1_hex(text):
    d = utf8(text)
    n = len(d)
    d.append(0x80)
    while len(d) % 64 != 56:
        d.append(0)
    bits = n * 8
    tail = []
    for i in range(8):
        q = bits // 256
        tail.append(bits - q * 256)
        bits = q
    for i in range(7, -1, -1):
        d.append(tail[i])
    h = [[0x2301, 0x6745], [0xab89, 0xefcd], [0xdcfe, 0x98ba], [0x5476, 0x1032], [0xe1f0, 0xc3d2]]
    K = [[0x7999, 0x5a82], [0xeba1, 0x6ed9], [0xbcdc, 0x8f1b], [0xc1d6, 0xca62]]
    for blk in range(0, len(d), 64):
        w = []
        for i in range(16):
            j = blk + i * 4
            w.append([(d[j + 2] << 8) | d[j + 3], (d[j] << 8) | d[j + 1]])
        for i in range(16, 80):
            x = [w[i - 3][0] ^ w[i - 8][0] ^ w[i - 14][0] ^ w[i - 16][0],
                 w[i - 3][1] ^ w[i - 8][1] ^ w[i - 14][1] ^ w[i - 16][1]]
            w.append(_rotl(x, 1))
        a = h[0]
        b = h[1]
        c = h[2]
        e4 = h[3]
        e = h[4]
        for i in range(80):
            if i < 20:
                f = [(b[0] & c[0]) | ((0xFFFF - b[0]) & e4[0]), (b[1] & c[1]) | ((0xFFFF - b[1]) & e4[1])]
                k = K[0]
            elif i < 40:
                f = [b[0] ^ c[0] ^ e4[0], b[1] ^ c[1] ^ e4[1]]
                k = K[1]
            elif i < 60:
                f = [(b[0] & c[0]) | (b[0] & e4[0]) | (c[0] & e4[0]),
                     (b[1] & c[1]) | (b[1] & e4[1]) | (c[1] & e4[1])]
                k = K[2]
            else:
                f = [b[0] ^ c[0] ^ e4[0], b[1] ^ c[1] ^ e4[1]]
                k = K[3]
            t = _add(_add(_add(_add(_rotl(a, 5), f), e), k), w[i])
            e = e4
            e4 = c
            c = _rotl(b, 30)
            b = a
            a = t
        h = [_add(h[0], a), _add(h[1], b), _add(h[2], c), _add(h[3], e4), _add(h[4], e)]
    digits = "0123456789abcdef"
    s = ""
    for wd in h:
        for v in (wd[1], wd[0]):
            for k in (12, 8, 4, 0):
                s = s + digits[(v >> k) & 15]
    return s


# ---- line-oriented connection helpers ----
class Line:
    """Wraps a PT TCPClient: buffers input, splits lines, dispatches."""

    def __init__(self, sock, on_line):
        self.sock = sock
        self.buf = ""
        self.on_line = on_line
        me = self

        def on_receive(data):          # PT calls plain functions only, not bound methods
            me._recv(data)
        sock.onReceive(on_receive)

    def _recv(self, data):
        self.buf = self.buf + data
        while "\n" in self.buf:
            i = self.buf.index("\n")
            line = self.buf[:i]
            self.buf = self.buf[i + 1:]
            if line != "":
                try:
                    self.on_line(self, line.split("|"))
                except Exception as e:
                    log("ERR", "handler: " + str(e))

    def send(self, fields):
        try:
            self.sock.send("|".join([str(f) for f in fields]) + "\n")
            return True
        except Exception as e:
            log("NET", "send failed: " + str(e))
            return False


class Server:
    """Listens on a port; handler(conn, rid, cmd, args) answers with conn.send([rid, ...])."""

    def __init__(self, name, port, handler):
        self.name = name
        self.port = port
        self.handler = handler
        self.srv = TCPServer()
        me = self

        def on_new_client(sock):       # PT calls plain functions only, not bound methods
            me._new(sock)
        self.srv.onNewClient(on_new_client)

    def start(self):
        self.srv.listen(self.port)
        log("NET", self.name + " listening on " + str(self.port))

    def _new(self, sock):
        Line(sock, self._line)

    def _line(self, conn, f):
        if len(f) < 2:
            return
        if f[1] == "HELLO":
            conn.send(["0", "WELCOME", self.name])
            return
        try:
            self.handler(conn, f[0], f[1], f[2:])
        except Exception as e:
            log("ERR", f[1] + ": " + str(e))
            conn.send([f[0], "ERR", clean(str(e))])


class Peer:
    """Outgoing connection with HELLO handshake, request ids and timeouts."""

    def __init__(self, name, ip, port):
        self.name = name
        self.ip = ip
        self.port = port
        self.ready = False
        self.conn = None
        self.tries = 0
        self.pending = {}
        self.next_id = [1]

    def _connect(self):
        if self.conn is not None:
            try:
                self.conn.sock.close()
            except Exception:
                pass
        sock = TCPClient()
        self.conn = Line(sock, self._line)
        sock.connect(self.ip, self.port)
        self.tries = 0

    def _line(self, conn, f):
        if len(f) >= 2 and f[0] == "0" and f[1] == "WELCOME":
            if not self.ready:
                log("NET", "connected to " + self.name + " " + self.ip + ":" + str(self.port))
            self.ready = True
            return
        rid = f[0]
        if rid in self.pending:
            cb = self.pending[rid][0]
            del self.pending[rid]
            cb(f[1:])

    def tick(self):
        if self.conn is None or (not self.ready and self.tries >= 20):
            self._connect()
        if not self.ready:
            self.tries = self.tries + 1
            self.conn.send(["0", "HELLO", self.name])
        dead = []
        for rid in self.pending:
            if TICK[0] - self.pending[rid][1] > TIMEOUT_TICKS:
                dead.append(rid)
        for rid in dead:
            cb = self.pending[rid][0]
            del self.pending[rid]
            cb(["ERR", "timeout " + self.name])

    def call(self, fields, cb):
        if not self.ready:
            cb(["ERR", self.name + " not connected"])
            return
        rid = "r" + str(self.next_id[0])
        self.next_id[0] = self.next_id[0] + 1
        self.pending[rid] = [cb, TICK[0]]
        self.conn.send([rid] + fields)


def run(tick_fn):
    while True:
        TICK[0] = TICK[0] + 1
        tick_fn()
        sleep(0.5)

# ================= USER client (host side): tokenizes, sends work, computes floats =================
USER = "user1"
PASSWORD = "pass1"
DISP = Peer("DISPATCHER", "192.168.20.20", 5000)

TEXT_A = "the quick brown fox jumps over the lazy dog"
TEXT_B = "the quick red fox runs past the sleepy cat"

SCENARIOS = {
    # full walk through the model
    "user1": [
        ["STATUS"],
        ["LOGIN"],
        ["INGEST", "doc1", TEXT_A],
        ["INGEST", "doc2", TEXT_B],
        ["QUERY", "INFO", "doc1"],
        ["QUERY", "UNION", "doc1", "doc2"],
        ["QUERY", "INTERSECT", "doc1", "doc2"],
        ["QUERY", "DRN", "doc1", "doc2"],
        ["QUERY", "HIST", "doc1"],
        ["QUERY", "LOOKUP", "doc1*doc2"],
        ["QUERY", "LIST"],
        ["QUERY", "STAT"],
    ],
    # same text as user1/doc1, other world (seed): other bits, other CID
    "user2": [
        ["LOGIN"],
        ["INGEST", "doc1", TEXT_A],
        ["QUERY", "INFO", "doc1"],
        ["QUERY", "LOOKUP", "doc1"],
        ["QUERY", "STAT"],
    ],
    # security checks: bad password, fake token, direct access to a board (ACL)
    "user3": [
        ["LOGIN_BAD"],
        ["FAKE_TOKEN"],
        ["DIRECT", "192.168.30.11", "5100"],
        ["LOGIN"],
        ["INGEST", "notes", "hllset worlds share one lattice"],
        ["QUERY", "HIST", "notes"],
    ],
}

STATE = {"step": 0, "wait": False, "token": "", "direct": None, "direct_ticks": 0}


def cardinality(counts):
    # Horvitz-Thompson estimate from the 32 integer counts c_s (float math stays on the host)
    n = 1024.0
    total = 0.0
    for c in counts:
        if c <= 0:
            continue
        if c >= 1024:
            total = total + n * math.log(n)
        else:
            total = total + (-n * math.log(1.0 - c / n))
    return int(total + 0.5)


def show(step, r):
    title = " ".join(step[:4]) if step[0] != "INGEST" else "INGEST " + step[1]
    if len(step) > 1 and step[0] == "QUERY" and step[1] == "HIST" and r[0] == "OK":
        counts = [int(x) for x in r[3].split(",")]
        log("USER", title + " -> c_s=" + r[3] + "  card~" + str(cardinality(counts)))
        return
    log("USER", title + " -> " + " | ".join(r))


def finish(step, r):
    show(step, r)
    STATE["wait"] = False
    STATE["step"] = STATE["step"] + 1


def run_step(step):
    cmd = step[0]
    STATE["wait"] = True
    if cmd == "STATUS":
        DISP.call(["STATUS"], lambda r: finish(step, r))
    elif cmd == "LOGIN" or cmd == "LOGIN_BAD":
        pw = PASSWORD if cmd == "LOGIN" else "wrong"

        def got(r):
            if r[0] == "OK":
                STATE["token"] = r[1]
                r = ["OK", "token " + r[1][:6] + "..."]
            finish(step, r)
        DISP.call(["LOGIN", USER, pw], got)
    elif cmd == "FAKE_TOKEN":
        DISP.call(["QUERY", "0000000000000000", "LIST"], lambda r: finish(step, r))
    elif cmd == "INGEST":
        DISP.call(["INGEST", STATE["token"], step[1], clean(step[2])], lambda r: finish(step, r))
    elif cmd == "QUERY":
        DISP.call(["QUERY", STATE["token"]] + step[1:], lambda r: finish(step, r))
    elif cmd == "DIRECT":
        STATE["direct"] = Peer("FPGA-direct", step[1], int(step[2]))
        STATE["direct_ticks"] = 0


def tick():
    DISP.tick()
    d = STATE["direct"]
    if d is not None:
        d.tick()
        STATE["direct_ticks"] = STATE["direct_ticks"] + 1
        if d.ready:
            STATE["direct"] = None
            finish(SCENARIOS[USER][STATE["step"]], ["OPEN", "board reachable directly - check ACL!"])
        elif STATE["direct_ticks"] > 12:
            STATE["direct"] = None
            finish(SCENARIOS[USER][STATE["step"]], ["BLOCKED", "no answer from board (ACL works)"])
        return
    steps = SCENARIOS[USER]
    if STATE["step"] >= len(steps):
        if STATE["step"] == len(steps):
            log("USER", "scenario finished")
            STATE["step"] = STATE["step"] + 1
        return
    if not STATE["wait"] and DISP.ready:
        run_step(steps[STATE["step"]])


def main():
    log("USER", USER + " client starting")
    run(tick)


if __name__ == "__main__":
    main()
